window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1ee0fea7afba1e0b"]={"versions": [{"id": "FIG-1ee0fea7afba1e0b", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Message Sequence Chart (MSC) bzw. TTCN-3 Graphical Presentation Format (GFT) zur Testfall-Spezifikation (Conformance Testing).</li>\n<li><strong>Architektur-Kontext:</strong> Auszug aus der Testfallspezifikation <code>AUTOSAR_CTSpec_Creation_Validation</code> (Release R3.0.7), Kapitel 11.2. Dargestellt ist das standardisierte Sequenzmuster zur Initialisierung eines BSW-Moduls (SUT – System Under Test) im Rahmen der automatisierten Konformitätsprüfung am Beispiel des <em>NVRAM Managers</em> (<code>NvM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test-Ports / Lifelines:</strong></li>\n<li><code>pt_NvMIf</code> (rechts): TTCN-3-Kommunikationsport der Testkomponente (MTC/PTC).</li>\n<li><code>pt_NvMIf</code> (links): Korrespondierender Port des SUT bzw. Test-Adapters zur BSW-Modulschnittstelle.</li>\n<li><strong>Dienste / Operationen:</strong></li>\n<li><code>NvM_Init</code>: Standardisierte AUTOSAR-Initialisierungs-API des NvM-Moduls (<code>void NvM_Init(void)</code>).</li>\n<li><strong>Wächter- & Kontrollstrukturen:</strong></li>\n<li><code>match NvM_Init</code>: Empfangsprüfung zur Verifikation, dass der empfangene Reply der aufgerufenen Signatur entspricht.</li>\n<li><code>t_guardtimer(0.031)</code>: Lokaler Guard-Timer (Wächter-Timer) mit einem Timeout von $31\\,\\text{ms}$ zur Überwachung der maximalen Antwortzeit des Modulaufrufs. Das <code>X</code>-Symbol markiert den expliziten Stopp/Cancel des Timers nach erfolgreichem Reply.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Aufruf (<code>call NvM_Init</code>):</strong> Die Testsuite setzt den synchronen Aufruf <code>call NvM_Init</code> über Port <code>pt_NvMIf</code> ab. Gleichzeitig wird der Überwachungs-Timer <code>t_guardtimer(0.031)</code> gestartet.</li>\n<li><strong>Abarbeitung im SUT:</strong> Das Modul durchläuft seine statische Initialisierungsroutine (Initialisierung interner Verwaltungstabellen, Zustandsvariablen und Blockdeskriptoren).</li>\n<li><strong>Rückkehr (<code>get reply NvM_Init</code>):</strong> Nach Beendigung der Routine signalisiert das SUT die Rückkehr an den Testport.</li>\n<li><strong>Verifikation & Timer-Reset:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Tester akzeptiert den Return (<code>match NvM_Init</code>).</li>\n<li>Vor Ablauf der $31\\,\\text{ms}$-Schwelle wird der <code>t_guardtimer</code> abgebrochen (<code>X</code>). Ein Überschreiten des Zeitfensters würde unmittelbar zum Testergebnis <code>fail</code> (Timeout-Fehler) führen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präkondition für Conformance-Tests:</strong> Fast alle funktionalen BSW-Testfälle setzen die Ausführung dieses Sequenzmusters voraus. APIs, die vor erfolgter Initialisierung aufgerufen werden, müssen normativ mit Fehlereintrag (Det-Meldung <code>NVM_E_NOT_INITIALIZED</code>) abgewiesen werden.</li>\n<li><strong>Deterministische Laufzeit:</strong> <code>NvM_Init</code> ist synchron und darf keine blockierenden Hardware-Operationen (z. B. synchrones Warten auf EEPROM/Flash-Treiber) ausführen. Die harte Obergrenze des Guard-Timers ($31\\,\\text{ms}$) verlangt, dass langwierige Lese-/Schreibvorgänge zwingend asynchron über die zyklische Task (<code>NvM_MainFunction</code>) bzw. Folgeaufträge wie <code>NvM_ReadAll</code> abgewickelt werden.</li>\n<li><strong>Port-Mapping im Test-Setup:</strong> Bei der Integration in Testumgebungen (z. B. CANoe/vTESTstudio oder TTCN-3-Toolchains) muss der Testadapter die C-Funktion direkt an den TTCN-3-Port <code>pt_NvMIf</code> binden, um den <code>call</code>/<code>reply</code>-Handshake transparent zu bedienen.</li>\n</ul>"}, {"id": "FIG-30fcd38f59d3497a", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Message Sequence Chart (MSC) bzw. TTCN-3 Graphical Presentation Format (GFT) zur Testfall-Spezifikation (Conformance Testing).</li>\n<li><strong>Architektur-Kontext:</strong> Auszug aus der Testfallspezifikation <code>AUTOSAR_CTSpec_Creation_Validation</code> (Release R3.0.7), Kapitel 11.2. Dargestellt ist das standardisierte Sequenzmuster zur Initialisierung eines BSW-Moduls (SUT – System Under Test) im Rahmen der automatisierten Konformitätsprüfung am Beispiel des <em>NVRAM Managers</em> (<code>NvM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test-Ports / Lifelines:</strong></li>\n<li><code>pt_NvMIf</code> (rechts): TTCN-3-Kommunikationsport der Testkomponente (MTC/PTC).</li>\n<li><code>pt_NvMIf</code> (links): Korrespondierender Port des SUT bzw. Test-Adapters zur BSW-Modulschnittstelle.</li>\n<li><strong>Dienste / Operationen:</strong></li>\n<li><code>NvM_Init</code>: Standardisierte AUTOSAR-Initialisierungs-API des NvM-Moduls (<code>void NvM_Init(void)</code>).</li>\n<li><strong>Wächter- & Kontrollstrukturen:</strong></li>\n<li><code>match NvM_Init</code>: Empfangsprüfung zur Verifikation, dass der empfangene Reply der aufgerufenen Signatur entspricht.</li>\n<li><code>t_guardtimer(0.031)</code>: Lokaler Guard-Timer (Wächter-Timer) mit einem Timeout von $31\\,\\text{ms}$ zur Überwachung der maximalen Antwortzeit des Modulaufrufs. Das <code>X</code>-Symbol markiert den expliziten Stopp/Cancel des Timers nach erfolgreichem Reply.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Aufruf (<code>call NvM_Init</code>):</strong> Die Testsuite setzt den synchronen Aufruf <code>call NvM_Init</code> über Port <code>pt_NvMIf</code> ab. Gleichzeitig wird der Überwachungs-Timer <code>t_guardtimer(0.031)</code> gestartet.</li>\n<li><strong>Abarbeitung im SUT:</strong> Das Modul durchläuft seine statische Initialisierungsroutine (Initialisierung interner Verwaltungstabellen, Zustandsvariablen und Blockdeskriptoren).</li>\n<li><strong>Rückkehr (<code>get reply NvM_Init</code>):</strong> Nach Beendigung der Routine signalisiert das SUT die Rückkehr an den Testport.</li>\n<li><strong>Verifikation & Timer-Reset:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Tester akzeptiert den Return (<code>match NvM_Init</code>).</li>\n<li>Vor Ablauf der $31\\,\\text{ms}$-Schwelle wird der <code>t_guardtimer</code> abgebrochen (<code>X</code>). Ein Überschreiten des Zeitfensters würde unmittelbar zum Testergebnis <code>fail</code> (Timeout-Fehler) führen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präkondition für Conformance-Tests:</strong> Fast alle funktionalen BSW-Testfälle setzen die Ausführung dieses Sequenzmusters voraus. APIs, die vor erfolgter Initialisierung aufgerufen werden, müssen normativ mit Fehlereintrag (Det-Meldung <code>NVM_E_NOT_INITIALIZED</code>) abgewiesen werden.</li>\n<li><strong>Deterministische Laufzeit:</strong> <code>NvM_Init</code> ist synchron und darf keine blockierenden Hardware-Operationen (z. B. synchrones Warten auf EEPROM/Flash-Treiber) ausführen. Die harte Obergrenze des Guard-Timers ($31\\,\\text{ms}$) verlangt, dass langwierige Lese-/Schreibvorgänge zwingend asynchron über die zyklische Task (<code>NvM_MainFunction</code>) bzw. Folgeaufträge wie <code>NvM_ReadAll</code> abgewickelt werden.</li>\n<li><strong>Port-Mapping im Test-Setup:</strong> Bei der Integration in Testumgebungen (z. B. CANoe/vTESTstudio oder TTCN-3-Toolchains) muss der Testadapter die C-Funktion direkt an den TTCN-3-Port <code>pt_NvMIf</code> binden, um den <code>call</code>/<code>reply</code>-Handshake transparent zu bedienen.</li>\n</ul>"}, {"id": "FIG-8dfd73a7e5e9a810", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Message Sequence Chart (MSC) bzw. TTCN-3 Graphical Presentation Format (GFT) zur Testfall-Spezifikation (Conformance Testing).</li>\n<li><strong>Architektur-Kontext:</strong> Auszug aus der Testfallspezifikation <code>AUTOSAR_CTSpec_Creation_Validation</code> (Release R3.0.7), Kapitel 11.2. Dargestellt ist das standardisierte Sequenzmuster zur Initialisierung eines BSW-Moduls (SUT – System Under Test) im Rahmen der automatisierten Konformitätsprüfung am Beispiel des <em>NVRAM Managers</em> (<code>NvM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test-Ports / Lifelines:</strong></li>\n<li><code>pt_NvMIf</code> (rechts): TTCN-3-Kommunikationsport der Testkomponente (MTC/PTC).</li>\n<li><code>pt_NvMIf</code> (links): Korrespondierender Port des SUT bzw. Test-Adapters zur BSW-Modulschnittstelle.</li>\n<li><strong>Dienste / Operationen:</strong></li>\n<li><code>NvM_Init</code>: Standardisierte AUTOSAR-Initialisierungs-API des NvM-Moduls (<code>void NvM_Init(void)</code>).</li>\n<li><strong>Wächter- & Kontrollstrukturen:</strong></li>\n<li><code>match NvM_Init</code>: Empfangsprüfung zur Verifikation, dass der empfangene Reply der aufgerufenen Signatur entspricht.</li>\n<li><code>t_guardtimer(0.031)</code>: Lokaler Guard-Timer (Wächter-Timer) mit einem Timeout von $31\\,\\text{ms}$ zur Überwachung der maximalen Antwortzeit des Modulaufrufs. Das <code>X</code>-Symbol markiert den expliziten Stopp/Cancel des Timers nach erfolgreichem Reply.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Aufruf (<code>call NvM_Init</code>):</strong> Die Testsuite setzt den synchronen Aufruf <code>call NvM_Init</code> über Port <code>pt_NvMIf</code> ab. Gleichzeitig wird der Überwachungs-Timer <code>t_guardtimer(0.031)</code> gestartet.</li>\n<li><strong>Abarbeitung im SUT:</strong> Das Modul durchläuft seine statische Initialisierungsroutine (Initialisierung interner Verwaltungstabellen, Zustandsvariablen und Blockdeskriptoren).</li>\n<li><strong>Rückkehr (<code>get reply NvM_Init</code>):</strong> Nach Beendigung der Routine signalisiert das SUT die Rückkehr an den Testport.</li>\n<li><strong>Verifikation & Timer-Reset:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Tester akzeptiert den Return (<code>match NvM_Init</code>).</li>\n<li>Vor Ablauf der $31\\,\\text{ms}$-Schwelle wird der <code>t_guardtimer</code> abgebrochen (<code>X</code>). Ein Überschreiten des Zeitfensters würde unmittelbar zum Testergebnis <code>fail</code> (Timeout-Fehler) führen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präkondition für Conformance-Tests:</strong> Fast alle funktionalen BSW-Testfälle setzen die Ausführung dieses Sequenzmusters voraus. APIs, die vor erfolgter Initialisierung aufgerufen werden, müssen normativ mit Fehlereintrag (Det-Meldung <code>NVM_E_NOT_INITIALIZED</code>) abgewiesen werden.</li>\n<li><strong>Deterministische Laufzeit:</strong> <code>NvM_Init</code> ist synchron und darf keine blockierenden Hardware-Operationen (z. B. synchrones Warten auf EEPROM/Flash-Treiber) ausführen. Die harte Obergrenze des Guard-Timers ($31\\,\\text{ms}$) verlangt, dass langwierige Lese-/Schreibvorgänge zwingend asynchron über die zyklische Task (<code>NvM_MainFunction</code>) bzw. Folgeaufträge wie <code>NvM_ReadAll</code> abgewickelt werden.</li>\n<li><strong>Port-Mapping im Test-Setup:</strong> Bei der Integration in Testumgebungen (z. B. CANoe/vTESTstudio oder TTCN-3-Toolchains) muss der Testadapter die C-Funktion direkt an den TTCN-3-Port <code>pt_NvMIf</code> binden, um den <code>call</code>/<code>reply</code>-Handshake transparent zu bedienen.</li>\n</ul>"}], "trans": [{"from": "FIG-1ee0fea7afba1e0b", "to": "FIG-30fcd38f59d3497a", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-30fcd38f59d3497a", "to": "FIG-8dfd73a7e5e9a810", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
